#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "ScoreTracker was a raw C++ pointer (UArenaScoreTracker*) without UPROPERTY, so the garbage collector could destroy it while the game mode still held the dangling pointer. The log shows GC at 21:05:13 and the crash (EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints, ArenaScoreTracker.cpp:18) at 21:05:27, after the first goal. Fixed by making ScoreTracker a UPROPERTY TObjectPtr in ArenaGameMode.h.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is not included in the packaged build. DefaultGame.ini only lists /Game/Data/Effects in DirectoriesToAlwaysCook, so /Game/Data/Palettes was never cooked into the pak. The log shows 'Couldn't find file for package /Game/Data/Palettes/DA_Primary' and 'Palette is null, using fallback gray'. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook."
}
